PRAGMA foreign_keys = ON;
CREATE TABLE assets (id INTEGER PRIMARY KEY AUTOINCREMENT, symbol TEXT NOT NULL UNIQUE, asset_type TEXT NOT NULL CHECK(asset_type IN ('crypto','stock','index')), provider TEXT NOT NULL, provider_symbol TEXT NOT NULL, active INTEGER NOT NULL DEFAULT 1, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE market_candles (asset_id INTEGER NOT NULL REFERENCES assets(id), timeframe TEXT NOT NULL, open_time INTEGER NOT NULL, open REAL NOT NULL, high REAL NOT NULL, low REAL NOT NULL, close REAL NOT NULL, volume REAL NOT NULL, provider TEXT NOT NULL, fetched_at TEXT NOT NULL, PRIMARY KEY(asset_id,timeframe,open_time));
CREATE INDEX idx_candles_lookup ON market_candles(asset_id,timeframe,open_time DESC);
CREATE TABLE model_versions (id TEXT PRIMARY KEY, name TEXT NOT NULL, status TEXT NOT NULL CHECK(status IN ('training','validation','active','retired','failed')), trained_through TEXT, metrics_json TEXT, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE analysis_results (id TEXT PRIMARY KEY, asset_id INTEGER NOT NULL REFERENCES assets(id), timeframe TEXT NOT NULL, as_of TEXT NOT NULL, engine_version TEXT NOT NULL, indicators_json TEXT NOT NULL, elliott_json TEXT, wyckoff_json TEXT, fibonacci_json TEXT, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE INDEX idx_analysis_latest ON analysis_results(asset_id,timeframe,as_of DESC);
CREATE TABLE prediction_records (id TEXT PRIMARY KEY, asset_id INTEGER NOT NULL REFERENCES assets(id), predicted_at TEXT NOT NULL, target_at TEXT NOT NULL, timeframe TEXT NOT NULL, bullish_probability REAL NOT NULL, sideways_probability REAL NOT NULL, bearish_probability REAL NOT NULL, model_version_id TEXT NOT NULL REFERENCES model_versions(id), status TEXT NOT NULL, CHECK(abs(bullish_probability+sideways_probability+bearish_probability-1.0)<0.0001));
CREATE INDEX idx_predictions_target ON prediction_records(asset_id,timeframe,target_at DESC);
CREATE TABLE prediction_outcomes (id INTEGER PRIMARY KEY AUTOINCREMENT, prediction_id TEXT NOT NULL UNIQUE REFERENCES prediction_records(id), actual_outcome TEXT NOT NULL CHECK(actual_outcome IN ('bullish','sideways','bearish')), observed_price REAL NOT NULL, resolved_at TEXT NOT NULL);
CREATE TABLE content_projects (id TEXT PRIMARY KEY, analysis_id TEXT REFERENCES analysis_results(id), language TEXT NOT NULL, duration_seconds INTEGER NOT NULL, template_id TEXT NOT NULL, subtitle_style TEXT, status TEXT NOT NULL, output_r2_key TEXT, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE social_accounts (id TEXT PRIMARY KEY, platform TEXT NOT NULL, account_label TEXT NOT NULL, encrypted_token_ref TEXT, status TEXT NOT NULL, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, UNIQUE(platform,account_label));
CREATE TABLE publish_jobs (id TEXT PRIMARY KEY, content_project_id TEXT NOT NULL REFERENCES content_projects(id), scheduled_at TEXT, idempotency_key TEXT NOT NULL UNIQUE, status TEXT NOT NULL, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE social_posts (id TEXT PRIMARY KEY, publish_job_id TEXT NOT NULL REFERENCES publish_jobs(id), social_account_id TEXT NOT NULL REFERENCES social_accounts(id), status TEXT NOT NULL, remote_post_id TEXT, post_url TEXT, failure_reason TEXT, retry_count INTEGER NOT NULL DEFAULT 0, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, UNIQUE(publish_job_id,social_account_id));
